#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

namespace {

// Basic dimension proto-structures
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// 2D fields: i x j, with j the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(field_layout, j_vec ^ i_vec);
	// 1D fictitious array over time
	DEFINE_PROTO_STRUCT(fict_layout, t_vec);

	// Tunable spatial blocking factors (compile-time constants)
	// These control the tile sizes used in the kernel and initialization.
	// They can be adjusted to better match specific cache hierarchies.
	static constexpr std::size_t block_i = 32; // tile height  (along 'i')
	static constexpr std::size_t block_j = 64; // tile width   (along 'j')
} tuning;

// Array initialization
void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Initialize fict[t] = t
	traverser(fict).for_each([=](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = (num_t)t;
	});

	// Dimensions
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Common blocked traversal for 2D fields:
	// - split 'i' and 'j' into tiles using into_blocks_dynamic
	// - hoist tile indices so we iterate over tiles first, then elements
	//
	// Using into_blocks_dynamic handles edge tiles automatically when
	// nx or ny are not exact multiples of the block sizes.
	constexpr auto bi = noarr::lit<tuning::block_i>;
	constexpr auto bj = noarr::lit<tuning::block_j>;

	auto block_ij =
		noarr::into_blocks_dynamic<'i', 'p', 'I', 'i'>(bi) ^ // 'p'  - presence flag (internal)
		noarr::into_blocks_dynamic<'j', 'q', 'J', 'j'>(bj) ^ // 'q'  - presence flag (internal)
		noarr::hoist<'I'>() ^                               // iterate tiles in 'i' first
		noarr::hoist<'J'>();                                // then tiles in 'j'

	// Initialize ex, ey, hz using a blocked traversal for better spatial locality
	traverser(ex, ey, hz)
		.order(block_ij)
		.for_each([=](auto state) {
			auto [i, j] = get_indices<'i', 'j'>(state);

			ex[state] = ((num_t)i * (j + 1)) / (num_t)nx;
			ey[state] = ((num_t)i * (j + 2)) / (num_t)ny;
			hz[state] = ((num_t)i * (j + 3)) / (num_t)nx;
		});
}

// Main computational kernel
//
// We keep the original FDTD equations and time-stepping semantics, but:
//
// 1. Use a blocked traversal (into_blocks_dynamic + hoist) for better cache
//    behavior on large grids.
// 2. Fuse the two interior field updates (ey and ex) into a single spatial
//    sweep to reduce memory traffic and improve reuse of hz(i,j).
// 3. Keep the hz update in a separate sweep that runs after ex/ey are fully
//    updated for the current time step, preserving the original dependencies.
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Precompute constants used in the stencil
	const num_t c0_5 = SCALAR_VAL(0.5);
	const num_t c0_7 = SCALAR_VAL(0.7);

	// Spatial blocking proto used inside each time step for interior sweeps.
	// As in init_array, we:
	// - split 'i' and 'j' into tiles (into_blocks_dynamic)
	// - hoist the tile indices so we iterate tile-by-tile
	constexpr auto bi = noarr::lit<tuning::block_i>;
	constexpr auto bj = noarr::lit<tuning::block_j>;

	auto block_ij =
		noarr::into_blocks_dynamic<'i', 'p', 'I', 'i'>(bi) ^
		noarr::into_blocks_dynamic<'j', 'q', 'J', 'j'>(bj) ^
		noarr::hoist<'I'>() ^
		noarr::hoist<'J'>();

#pragma scop
	// Outer time loop over t
	traverser(fict, ex, ey, hz).template for_dims<'t'>([=](auto trav_t) {
		// State with only the current time index
		auto t_state = trav_t.state();

		// ------------------------------------------------------------------
		// 1) Boundary condition:
		//    ey[0][j] = fict[t] for all j
		// ------------------------------------------------------------------
		trav_t
			.order(noarr::fix<'i'>(0)) // restrict to i == 0
			.for_each([=](auto state) {
				// state has i = 0, all j; t is carried by t_state
				ey[state] = fict[t_state];
			});

		// ------------------------------------------------------------------
		// 2) Interior E-field updates (fused ey and ex sweeps)
		//
		// Original equations:
		//
		//   ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]),
		//     for i = 1..nx-1, j = 0..ny-1
		//
		//   ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]),
		//     for i = 0..nx-1, j = 1..ny-1
		//
		// We traverse the full domain i in [0, nx-1], j in [0, ny-1]
		// using a blocked order and perform the updates where their
		// respective index conditions are satisfied. The fused form:
		//
		//   if (i > 0) ey-update;
		//   if (j > 0) ex-update;
		//
		// is equivalent to the original two sweeps:
		// - both use only old values of hz, ey, ex
		// - hz is not written in this phase
		// - ex and ey are independent of each other
		// - hz-update is done later, after this whole phase finishes
		// ------------------------------------------------------------------
		trav_t
			.order(block_ij)
			.for_each([=](auto state) {
				const auto [i, j] = get_indices<'i', 'j'>(state);
				const auto hz_ij = hz[state];

				// ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j]), i >= 1
				if (i > 0) {
					auto state_im1j = state - noarr::idx<'i'>(1);
					ey[state] = ey[state] - c0_5 * (hz_ij - hz[state_im1j]);
				}

				// ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1]), j >= 1
				if (j > 0) {
					auto state_ijm1 = state - noarr::idx<'j'>(1);
					ex[state] = ex[state] - c0_5 * (hz_ij - hz[state_ijm1]);
				}
			});

		// ------------------------------------------------------------------
		// 3) Magnetic field update:
		//
		//   hz[i][j] = hz[i][j] - 0.7 * (
		//                  ex[i][j+1] - ex[i][j]
		//                + ey[i+1][j] - ey[i][j])
		//     for i = 0..nx-2, j = 0..ny-2
		//
		// This uses the *new* ex and ey values from step 2 above.
		// We first restrict to the interior spatial domain using slices,
		// then apply the same blocked traversal to improve locality.
		// ------------------------------------------------------------------
		auto hz_domain =
			noarr::slice<'i'>(0, nx - 1) ^ // i: 0..nx-2
			noarr::slice<'j'>(0, ny - 1);  // j: 0..ny-2

		trav_t
			.order(hz_domain ^ block_ij)
			.for_each([=](auto state) {
				// state: i in [0, nx-2], j in [0, ny-2]
				auto state_i_jp1 = state + noarr::idx<'j'>(1);
				auto state_ip1_j = state + noarr::idx<'i'>(1);

				hz[state] = hz[state]
				            - c0_7 * (
					            (ex[state_i_jp1] - ex[state]) +
					            (ey[state_ip1_j] - ey[state])
				            );
			});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t tmax = TMAX;
	std::size_t nx = NX;
	std::size_t ny = NY;

	// Set lengths for spatial and temporal dimensions
	auto set_space = noarr::set_length<'i'>(nx) ^ noarr::set_length<'j'>(ny);
	auto set_time  = noarr::set_length<'t'>(tmax);

	// Allocate bags
	auto ex = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto ey = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto hz = noarr::bag(noarr::scalar<num_t>() ^ tuning.field_layout ^ set_space);
	auto fict = noarr::bag(noarr::scalar<num_t>() ^ tuning.fict_layout ^ set_time);

	// Initialize arrays
	init_array(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	// Start timer
	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_fdtd_2d(ex.get_ref(), ey.get_ref(), hz.get_ref(), fict.get_ref());

	// Stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print results (if requested, mimicking PolyBench's conditional printing)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);

		// Hoist 'i' so each row is contiguous in the serialized output
		noarr::serialize_data(std::cerr, ex.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, ey.get_ref() ^ noarr::hoist<'i'>());
		noarr::serialize_data(std::cerr, hz.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print elapsed time (seconds)
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
