// Main computational kernel
//   FDTD-2D time stepping on a 2D grid.
//
//   This version keeps the original numerical scheme but improves spatial
//   traversal by:
//     * tiling the i×j iteration space using into_blocks_static
//     * hoisting block indices so that the outer loops run over blocks
//     * keeping j as the innermost (contiguous) dimension
//   The tiling factors are compile-time constants and can be tuned.
// -----------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Problem dimensions (runtime)
	const std::size_t nx = ex | get_length<'i'>();
	const std::size_t ny = ex | get_length<'j'>();

	// Tunable block sizes for the spatial traversal.
	// These are compile-time constants, but can be changed to tune
	// performance for a particular machine/cache hierarchy.
	constexpr std::size_t I_BLOCK = 32; // tile size in the i (row) dimension
	constexpr std::size_t J_BLOCK = 64; // tile size in the j (column) dimension

	// Common constants used in the update formulas
	const num_t c0 = SCALAR_VAL(0.5);
	const num_t c1 = SCALAR_VAL(0.7);

	// Proto-structure describing a tiled traversal of the i×j space.
	//
	// - into_blocks_static<'i', 'b', 'I', 'i'>(I_BLOCK)
	//     splits the original 'i' dimension into:
	//       'b' : body/border selector (handled internally by Noarr)
	//       'I' : block index in i
	//       'i' : index within the block
	//
	// - into_blocks_static<'j', 'c', 'J', 'j'>(J_BLOCK)
	//     does the same for the 'j' dimension.
	//
	// - hoist<'I'>(), hoist<'J'>()
	//     move the block indices to the top of the signature, so the
	//     traverser iterates in block-major order:
	//       outer loops:   I, J (blocks)
	//       inner loops:   i, j (within a block, j contiguous)
	//
	// All these transformations are *view-only* (they do not change the
	// physical layout) and are therefore safe to use in traverser::order.
	constexpr auto blocked_ij =
		noarr::into_blocks_static<'i', 'b', 'I', 'i'>(noarr::lit<I_BLOCK>) ^
		noarr::into_blocks_static<'j', 'c', 'J', 'j'>(noarr::lit<J_BLOCK>) ^
		noarr::hoist<'I'>() ^
		noarr::hoist<'J'>();

	// Spatial traverser over the three 2D fields.
	// We reuse this traverser in all spatial sweeps within a time step.
	auto trav_space = noarr::traverser(ex, ey, hz);

#pragma scop
	// Time-stepping loop.
	// Only 'fict' has the 't' dimension, so we traverse just over it
	// and perform the spatial sweeps inside.
	traverser(fict).template for_dims<'t'>([=](auto trav_t) {
		// trav_t has 't' fixed; obtain the corresponding state
		auto t_state = trav_t.state();

		// Read fict[t] once per time step and reuse the scalar.
		const num_t fict_t = fict[t_state];

		// -----------------------------------------------------------------
		// 1) Boundary condition on ey:
		//      ey[0][j] = fict[t]  for all j
		//
		// We only iterate along 'j', which is contiguous in memory.
		// This is a simple 1D traversal over the first row.
		// -----------------------------------------------------------------
		traverser(ey)
			.order(noarr::fix<'i'>(0)) // fix i = 0, leave j varying
			.for_each([=](auto state) {
				ey[state] = fict_t;
			});

		// -----------------------------------------------------------------
		// 2) Update ey interior:
		//      ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j])
		//      for i = 1..nx-1, j = 0..ny-1
		//
		// We restrict 'i' to [1, nx-1] using slice, then tile the
		// resulting i×j space with blocked_ij. Noarr takes care of
		// handling partial tiles (borders) via into_blocks_static.
		// -----------------------------------------------------------------
		trav_space
			.order(
				noarr::slice<'i'>(1, nx - 1) // i ∈ [1, nx-1]
				^ blocked_ij                 // tiled traversal over i×j
			)
			.for_each([=](auto state) {
				// state: i ∈ [1, nx-1], j ∈ [0, ny-1]
				auto state_im1j = state - noarr::idx<'i'>(1);

				ey[state] = ey[state] - c0 * (hz[state] - hz[state_im1j]);
			});

		// -----------------------------------------------------------------
		// 3) Update ex interior:
		//      ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1])
		//      for i = 0..nx-1, j = 1..ny-1
		//
		// This time we restrict 'j' to [1, ny-1], but reuse the same
		// blocked traversal pattern.
		// -----------------------------------------------------------------
		trav_space
			.order(
				noarr::slice<'j'>(1, ny - 1) // j ∈ [1, ny-1]
				^ blocked_ij
			)
			.for_each([=](auto state) {
				// state: i ∈ [0, nx-1], j ∈ [1, ny-1]
				auto state_ijm1 = state - noarr::idx<'j'>(1);

				ex[state] = ex[state] - c0 * (hz[state] - hz[state_ijm1]);
			});

		// -----------------------------------------------------------------
		// 4) Update hz interior:
		//      hz[i][j] = hz[i][j]
		//                 - 0.7 * (ex[i][j+1] - ex[i][j]
		//                          + ey[i+1][j] - ey[i][j])
		//      for i = 0..nx-2, j = 0..ny-2
		//
		// We slice both dimensions to exclude the last row and column,
		// then apply the same tiled traversal.
		// -----------------------------------------------------------------
		trav_space
			.order(
				noarr::slice<'i'>(0, nx - 1) ^ // i ∈ [0, nx-2]
				noarr::slice<'j'>(0, ny - 1) ^ // j ∈ [0, ny-2]
				blocked_ij
			)
			.for_each([=](auto state) {
				// state: i ∈ [0, nx-2], j ∈ [0, ny-2]
				auto state_i_jp1 = state + noarr::idx<'j'>(1);
				auto state_ip1_j = state + noarr::idx<'i'>(1);

				hz[state] = hz[state]
				            - c1 * ((ex[state_i_jp1] - ex[state]) +
				                    (ey[state_ip1_j] - ey[state]));
			});
	});
