#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// 2D fields: i x j, with j the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(field_layout, j_vec ^ i_vec);
	// 1D fictitious array over time
	DEFINE_PROTO_STRUCT(fict_layout, t_vec);

	// ---------------------------------------------------------------------
	// Tunable tile sizes for the 2D spatial sweeps.
	// These control the size of blocks processed by the kernel in the
	// i (outer) and j (inner, contiguous) dimensions.
	//
	// They are chosen so that a tile of ex/ey/hz for one time-step fits
	// reasonably well into L1 cache on a modern x64 core, but they can be
	// adjusted for different machines.
	// ---------------------------------------------------------------------
	static constexpr std::size_t tile_i = 32; // rows per tile
	static constexpr std::size_t tile_j = 64; // columns per tile
} tuning;

// -----------------------------------------------------------------------------
// Small helper: 2D tiled traversal over (i, j) using a base traverser.
//
// The helper:
//   * restricts the iteration to the rectangular domain
//       i in [i_start, i_start + i_len)
//       j in [j_start, j_start + j_len)
//   * applies a 2D tiling of sizes (tile_i, tile_j) over the "body"
//       i in [i_start, i_start + i_body)   where i_body is a multiple of tile_i
//       j in [j_start, j_start + j_body)   where j_body is a multiple of tile_j
//   * handles the remaining "edge" regions without tiling:
//       - right edge  : i in [i_start, i_start + i_body),   j in [j_start + j_body, j_start + j_len)
//       - bottom band : i in [i_start + i_body, i_start + i_len), j in [j_start, j_start + j_len)
//
// The function preserves the original index semantics: the state passed to
// `func` always contains the original indices 'i' and 'j' (and 't', fixed by
// the caller), so the update code does not need to be aware of the tiling.
// -----------------------------------------------------------------------------
template<class TraverserT, class Func>
inline void tiled_for_each_ij(const TraverserT &trav,
                              std::size_t i_start, std::size_t i_len,
                              std::size_t j_start, std::size_t j_len,
                              std::size_t tile_i,  std::size_t tile_j,
                              const Func &func) {
	using namespace noarr;

	if (i_len == 0 || j_len == 0)
		return;

	const std::size_t i_body = (i_len / tile_i) * tile_i; // multiple of tile_i, <= i_len
	const std::size_t j_body = (j_len / tile_j) * tile_j; // multiple of tile_j, <= j_len

	// -----------------------------
	// 1) 2D tiled interior region
	//    i in [i_start, i_start + i_body)
	//    j in [j_start, j_start + j_body)
	// -----------------------------
	if (i_body > 0 && j_body > 0) {
		// Order:
		//   1. Slice to the rectangular body region.
		//   2. Split j into tiles (J = tile index, j = intra-tile column).
		//   3. Hoist J to iterate tiles in j-major order.
		//   4. Split i into tiles (I = tile index, i = intra-tile row).
		//   5. Hoist I so tiles are traversed in (I, J) order.
		//
		// This results in an iteration order:
		//   for each I (tile of rows)
		//     for each J (tile of columns)
		//       for each i in tile (row)
		//         for each j in tile (column, contiguous)
		//
		// The state passed to `func` still only sees the original 'i' and 'j'.
		auto proto_tiled =
			  slice<'i'>(i_start, i_body)
			^ slice<'j'>(j_start, j_body)
			^ into_blocks<'j', 'J', 'j'>(tile_j)
			^ hoist<'J'>()
			^ into_blocks<'i', 'I', 'i'>(tile_i)
			^ hoist<'I'>();

		trav.order(proto_tiled).for_each(func);
	}

	// -----------------------------
	// 2) Right edge (columns not covered by tiling in j)
	//    i in [i_start, i_start + i_body)
	//    j in [j_start + j_body, j_start + j_len)
	// -----------------------------
	if (i_body > 0 && j_len > j_body) {
		auto proto_right =
			  slice<'i'>(i_start, i_body)
			^ slice<'j'>(j_start + j_body, j_len - j_body);

		trav.order(proto_right).for_each(func);
	}

	// -----------------------------
	// 3) Bottom band (rows not covered by tiling in i)
	//    i in [i_start + i_body, i_start + i_len)
	//    j in [j_start,          j_start + j_len)
	// -----------------------------
	if (i_len > i_body) {
		auto proto_bottom =
			  slice<'i'>(i_start + i_body, i_len - i_body)
			^ slice<'j'>(j_start,          j_len);

		trav.order(proto_bottom).for_each(func);
	}
}

// Array initialization
void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Initialize fict[t] = t
	traverser(fict).for_each([=](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = (num_t)t;
	});

	// Dimensions
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Initialize ex, ey, hz
	traverser(ex, ey, hz).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		ex[state] = ((num_t)i * (j + 1)) / (num_t)nx;
		ey[state] = ((num_t)i * (j + 2)) / (num_t)ny;
		hz[state] = ((num_t)i * (j + 3)) / (num_t)nx;
	});
}

// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// BLAS-like params in original:
	// Time-stepping FDTD on a 2D grid

#pragma scop
	// Outer time loop over t
	traverser(fict, ex, ey, hz).template for_dims<'t'>([=](auto trav_t) {
		// State with only the current time index
		auto t_state = trav_t.state();

		// -----------------------------------------------------------------
		// ey[0][j] = fict[t] for all j
		// This is a single boundary row, already perfectly contiguous in j.
		// -----------------------------------------------------------------
		trav_t
			.order(fix<'i'>(0))
			.for_each([=](auto state) {
				// state has i=0, all j; t in t_state
				ey[state] = fict[t_state];
			});

		// -----------------------------------------------------------------
		// ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j])
		// for i = 1..nx-1, j = 0..ny-1
		//
		// We process this rectangular region using 2D tiling to improve
		// cache locality (especially in the i dimension) while keeping
		// j as the innermost, contiguous dimension.
		// -----------------------------------------------------------------
		{
			const std::size_t i_start = 1;
			const std::size_t i_len   = nx - 1; // i in [1, nx-1]
			const std::size_t j_start = 0;
			const std::size_t j_len   = ny;     // j in [0, ny-1]

			tiled_for_each_ij(
				trav_t,
				i_start, i_len,
				j_start, j_len,
				tuning::tile_i, tuning::tile_j,
				[=](auto state) {
					// state: i in [1, nx-1], j in [0, ny-1]
					auto state_im1j = state - noarr::idx<'i'>(1);

					ey[state] = ey[state]
					            - SCALAR_VAL(0.5) * (hz[state] - hz[state_im1j]);
				}
			);
		}

		// -----------------------------------------------------------------
		// ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1])
		// for i = 0..nx-1, j = 1..ny-1
		//
		// Again, we apply 2D tiling over (i, j) within the valid range.
		// -----------------------------------------------------------------
		{
			const std::size_t i_start = 0;
			const std::size_t i_len   = nx;     // i in [0, nx-1]
			const std::size_t j_start = 1;
			const std::size_t j_len   = ny - 1; // j in [1, ny-1]

			tiled_for_each_ij(
				trav_t,
				i_start, i_len,
				j_start, j_len,
				tuning::tile_i, tuning::tile_j,
				[=](auto state) {
					// state: i in [0, nx-1], j in [1, ny-1]
					auto state_ijm1 = state - noarr::idx<'j'>(1);

					ex[state] = ex[state]
					            - SCALAR_VAL(0.5) * (hz[state] - hz[state_ijm1]);
				}
			);
		}

		// -----------------------------------------------------------------
		// hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j]
		//                             + ey[i+1][j] - ey[i][j])
		// for i = 0..nx-2, j = 0..ny-2
		//
		// This is the heaviest stencil-like update. We tile the interior
		// domain in both i and j to keep a working set of ex/ey/hz for a
		// tile in cache, while still visiting j contiguously.
		// -----------------------------------------------------------------
		{
			const std::size_t i_start = 0;
			const std::size_t i_len   = nx - 1; // i in [0, nx-2]
			const std::size_t j_start = 0;
			const std::size_t j_len   = ny - 1; // j in [0, ny-2]

			tiled_for_each_ij(
				trav_t,
				i_start, i_len,
				j_start, j_len,
				tuning::tile_i, tuning::tile_j,
				[=](auto state) {
					// state: i in [0, nx-2], j in [0, ny-2]
					auto state_i_jp1 = state + noarr::idx<'j'>(1);
					auto state_ip1_j = state + noarr::idx<'i'>(1);

					hz[state] = hz[state]
					            - SCALAR_VAL(0.7) * (
						            (ex[state_i_jp1] - ex[state]) +
						            (ey[state_ip1_j] - ey[state])
					            );
				}
			);
		}
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t tmax = TMAX;
	std::size_t nx = NX;
	std::size_t ny = NY;

	// Set lengths for spatial and temporal dimensions
	auto set_space = noarr::set_length<'i'>(nx) ^ noarr::set_length<'j'>(ny);
	auto set_time  = noarr::set_length<'t'>(tmax);

