using num_t = DATA_TYPE;

namespace {

// -----------------------------------------------------------------------------
// Layout tuning & blocking parameters
// -----------------------------------------------------------------------------

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// 2D fields: i x j, with j the inner (contiguous) dimension
	// Layout: scalar<num_t> ^ vector<'j'> ^ vector<'i'>
	//  - 'i' is the outer (row) dimension
	//  - 'j' is the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(field_layout, j_vec ^ i_vec);

	// 1D fictitious array over time
	DEFINE_PROTO_STRUCT(fict_layout, t_vec);

	// Tunable blocking factors for the hz update.
	// The hz kernel operates on the domain:
	//   i in [0, nx-2]  (length nx-1)
	//   j in [0, ny-2]  (length ny-1)
	// We only enable blocking when (nx-1) and (ny-1) are multiples of
	// these block sizes, so correctness is preserved for arbitrary sizes.
	//
	// The defaults (31 x 31) are chosen so that for the PolyBench default
	// NX = NY = 1024, the interior lengths (1023) are exactly divisible:
	//   1023 = 3 * 11 * 31
	// A 31 x 31 tile with three 2D fields (ex, ey, hz) of double precision
	// is ~23 kB, which fits comfortably into a 32 kB L1 data cache.
	static constexpr std::size_t hz_block_i = 31;
	static constexpr std::size_t hz_block_j = 31;
} tuning;

// -----------------------------------------------------------------------------
// Array initialization
// -----------------------------------------------------------------------------

void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Initialize fict[t] = t
	traverser(fict).for_each([=](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = static_cast<num_t>(t);
	});

	// Dimensions
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Initialize ex, ey, hz.
	// Traversal order: i outer, j inner (row-major in terms of i/j indices,
	// but with j contiguous in memory as encoded in field_layout).
	traverser(ex, ey, hz).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		ex[state] = (static_cast<num_t>(i) * (j + 1)) / static_cast<num_t>(nx);
		ey[state] = (static_cast<num_t>(i) * (j + 2)) / static_cast<num_t>(ny);
		hz[state] = (static_cast<num_t>(i) * (j + 3)) / static_cast<num_t>(nx);
	});
}

// -----------------------------------------------------------------------------
// Main computational kernel
//
// FDTD-2D, time stepping on a 2D grid:
//
// 1) ey[0][j]          = fict[t]
// 2) ey[i][j]         -= 0.5 * (hz[i][j]   - hz[i-1][j])
// 3) ex[i][j]         -= 0.5 * (hz[i][j]   - hz[i][j-1])
// 4) hz[i][j]         -= 0.7 * (ex[i][j+1] - ex[i][j]
//                                + ey[i+1][j] - ey[i][j])
//
// We keep the original update equations and ordering (1,2,3,4) but
// specialize the traversal for the hz update with a tunable 2D tiling
// using noarr::into_blocks and hoisting the block indices to the top
// of the loop nest. For sizes where the interior is not divisible by
// the tile size, we transparently fall back to the original traversal.
// -----------------------------------------------------------------------------

[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Spatial dimensions
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Scalar coefficients (material parameters); pulled out once so that
	// the compiler does not have to materialize SCALAR_VAL(...) repeatedly.
	const num_t coeff_e = SCALAR_VAL(0.5);
	const num_t coeff_h = SCALAR_VAL(0.7);

	// -------------------------------------------------------------------------
	// Pre-built proto-structures for spatial traversals
	// (These are reused in each time step.)
	// -------------------------------------------------------------------------

	// ey boundary: ey[0][j] = fict[t]  (fix row i = 0)
	const auto ey_boundary_order =
		fix<'i'>(0);

	// ey interior: i in [1, nx-1], j in [0, ny-1]
	const auto ey_update_order =
		slice<'i'>(1, nx - 1);

	// ex interior: i in [0, nx-1], j in [1, ny-1]
	const auto ex_update_order =
		slice<'j'>(1, ny - 1);

	// hz interior baseline order:
	//   i in [0, nx-2] (length nx-1),
	//   j in [0, ny-2] (length ny-1),
	// traversed in row-major (i outer, j inner) fashion.
	const auto hz_update_order_basic =
		slice<'i'>(0, nx - 1) ^
		slice<'j'>(0, ny - 1);

	// Determine whether we can use 2D blocking for the hz update.
	// We only use blocking when the interior extents are exact multiples
	// of the chosen tile sizes; otherwise we keep the original order.
	const auto hz_interior_len_i = nx > 0 ? (nx - 1) : 0;
	const auto hz_interior_len_j = ny > 0 ? (ny - 1) : 0;

	const bool can_block_hz =
		(hz_interior_len_i > 0 && hz_interior_len_j > 0) &&
		(hz_interior_len_i % tuning.hz_block_i == 0) &&
		(hz_interior_len_j % tuning.hz_block_j == 0);

	// Blocked traversal for hz:
	//  - First restrict to the interior via slice (same as basic order),
	//  - then split 'i' into blocks I x i and 'j' into blocks J x j,
	//  - then hoist I and J so the block loops are outermost:
	//
	//    for I
	//      for J
	//        for i in block
	//          for j in block
	//
	// The states handed to the user callback still contain only 'i' and 'j'
	// coordinates (block indices are internal to the traverser), so the
	// update expression is identical to the baseline version.
	const auto hz_update_order_blocked =
		hz_update_order_basic
		^ into_blocks<'i', 'I', 'i'>(tuning.hz_block_i)
		^ into_blocks<'j', 'J', 'j'>(tuning.hz_block_j)
		^ hoist<'I'>()
		^ hoist<'J'>();

#pragma scop
	// Outer time loop over t
	traverser(fict, ex, ey, hz).template for_dims<'t'>([=](auto trav_t) {
		// State with only the current time index
		auto t_state = trav_t.state();

		// ---------------------------------------------------------------------
		// 1) ey[0][j] = fict[t]  for all j
		// ---------------------------------------------------------------------
		trav_t
			.order(ey_boundary_order)
			.for_each([=](auto state) {
				// state has i=0, j in [0, ny-1]
				ey[state] = fict[t_state];
			});

		// ---------------------------------------------------------------------
		// 2) ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j])
		//    for i = 1..nx-1, j = 0..ny-1
		//
		// Traversal order:
		//   i in [1, nx-1]  (outer)
		//   j in [0, ny-1]  (inner, contiguous)
		// ---------------------------------------------------------------------
		trav_t
			.order(ey_update_order)
			.for_each([=](auto state) {
				// state: i in [1, nx-1], j in [0, ny-1]
				auto state_im1j = state - idx<'i'>(1);

				ey[state] = ey[state]
				            - coeff_e * (hz[state] - hz[state_im1j]);
			});

		// ---------------------------------------------------------------------
		// 3) ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1])
		//    for i = 0..nx-1, j = 1..ny-1
		//
		// Traversal order:
		//   i in [0, nx-1]  (outer)
		//   j in [1, ny-1]  (inner, contiguous)
		// ---------------------------------------------------------------------
		trav_t
			.order(ex_update_order)
			.for_each([=](auto state) {
				// state: i in [0, nx-1], j in [1, ny-1]
				auto state_ijm1 = state - idx<'j'>(1);

				ex[state] = ex[state]
				            - coeff_e * (hz[state] - hz[state_ijm1]);
			});

		// ---------------------------------------------------------------------
		// 4) hz[i][j] -= 0.7 * (ex[i][j+1] - ex[i][j]
		//                       + ey[i+1][j] - ey[i][j])
		//    for i = 0..nx-2, j = 0..ny-2
		//
		// We provide two traversal strategies:
		//
		//  - Baseline: single row-major scan over the interior.
		//  - Blocked : 2D tiling over (i,j) with tunable tile size,
		//              using noarr::into_blocks and hoist so that the
		//              block loops are outer and the within-block loops
		//              still iterate j contiguously.
		//
		// Both produce *exactly* the same set of (i,j) index states; only
		// the visitation order changes.
		// ---------------------------------------------------------------------
		if (can_block_hz) {
			// Blocked interior traversal
			trav_t
				.order(hz_update_order_blocked)
				.for_each([=](auto state) {
					// state: i in [0, nx-2], j in [0, ny-2]
					auto state_i_jp1 = state + idx<'j'>(1); // (i, j+1)
					auto state_ip1_j = state + idx<'i'>(1); // (i+1, j)

					hz[state] = hz[state]
					            - coeff_h * (
						            (ex[state_i_jp1] - ex[state]) +
						            (ey[state_ip1_j] - ey[state])
					            );
				});
		} else {
			// Fallback: original simple row-major traversal
			trav_t
				.order(hz_update_order_basic)
				.for_each([=](auto state) {
					// state: i in [0, nx-2], j in [0, ny-2]
					auto state_i_jp1 = state + idx<'j'>(1); // (i, j+1)
					auto state_ip1_j = state + idx<'i'>(1); // (i+1, j)

					hz[state] = hz[state]
					            - coeff_h * (
						            (ex[state_i_jp1] - ex[state]) +
						            (ey[state_ip1_j] - ey[state])
					            );
				});
		}
	});
#pragma endscop
