	auto ny = ex | get_length<'j'>();

	// Tunable spatial blocking factors.
	// Adjust these for different cache hierarchies / vector widths.
	constexpr std::size_t TILE_I = 32; // tile size in i (outer) dimension
	constexpr std::size_t TILE_J = 64; // tile size in j (inner / contiguous) dimension

	// Common 2D blocking pattern:
	// - Split 'i' into (border dim 'B', block index 'I', intra-block index 'i')
	// - Split 'j' into (border dim 'C', block index 'J', intra-block index 'j')
	// - Hoist block indices so that blocks are traversed in the outer loops,
	//   while 'j' (the contiguous dimension) remains innermost.
	//
	// We use into_blocks_static so that incomplete tiles (borders) are handled
	// correctly for arbitrary nx, ny. All newly introduced dimensions are
	// internal to the traversal; the states passed to the lambdas still only
	// contain 'i' and 'j'.
	constexpr auto space_blocking =
		noarr::into_blocks_static<'i', 'B', 'I', 'i'>(noarr::lit<TILE_I>)
		^ noarr::hoist<'B'>()
		^ noarr::hoist<'I'>()
		^ noarr::into_blocks_static<'j', 'C', 'J', 'j'>(noarr::lit<TILE_J>)
		^ noarr::hoist<'C'>()
		^ noarr::hoist<'J'>();

	// For the boundary update ey[0][j] we only need to walk a single row,
	// so we block only in 'j' and fix i = 0.
	constexpr auto row_blocking =
		noarr::into_blocks_static<'j', 'C', 'J', 'j'>(noarr::lit<TILE_J>)
		^ noarr::hoist<'C'>()
		^ noarr::hoist<'J'>()
		^ noarr::fix<'i'>(0);

	// Hoist constants outside the inner loops
	const num_t c_half = SCALAR_VAL(0.5);
	const num_t c_07   = SCALAR_VAL(0.7);

	// BLAS-like params in original:
	// Time-stepping FDTD on a 2D grid
#pragma scop
	// Outer time loop over t
	traverser(fict, ex, ey, hz).template for_dims<'t'>([=](auto trav_t) {
		// State with only the current time index
		auto t_state = trav_t.state();

		// ------------------------------------------------------------------
		// 1) Boundary condition:
		//    ey[0][j] = fict[t]   for all j
		// ------------------------------------------------------------------
		trav_t
			// Block in j, keep i = 0 fixed
			.order(row_blocking)
			.for_each([=](auto state) {
				// state has i = 0, j in [0, ny)
				ey[state] = fict[t_state];
			});

		// ------------------------------------------------------------------
		// 2) Update ey in the interior:
		//    ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j])
		//    for i = 1..nx-1, j = 0..ny-1
		// ------------------------------------------------------------------
		trav_t
			// Block the full 2D space, then restrict i to [1, nx-1]
			.order(space_blocking ^ noarr::slice<'i'>(1, nx - 1))
			.for_each([=](auto state) {
				// state: i in [1, nx-1], j in [0, ny-1]
				auto state_im1j = state - noarr::idx<'i'>(1);

				ey[state] = ey[state]
				            - c_half * (hz[state] - hz[state_im1j]);
			});

		// ------------------------------------------------------------------
		// 3) Update ex in the interior:
		//    ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1])
		//    for i = 0..nx-1, j = 1..ny-1
		// ------------------------------------------------------------------
		trav_t
			// Block the full 2D space, then restrict j to [1, ny-1]
			.order(space_blocking ^ noarr::slice<'j'>(1, ny - 1))
			.for_each([=](auto state) {
				// state: i in [0, nx-1], j in [1, ny-1]
				auto state_ijm1 = state - noarr::idx<'j'>(1);

				ex[state] = ex[state]
				            - c_half * (hz[state] - hz[state_ijm1]);
			});

		// ------------------------------------------------------------------
		// 4) Update hz in the interior:
		//    hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j]
		//                                 + ey[i+1][j] - ey[i][j])
		//    for i = 0..nx-2, j = 0..ny-2
		// ------------------------------------------------------------------
		trav_t
			// Block the full 2D space, then restrict
			//   i to [0, nx-2]  -> slice<'i'>(0, nx - 1)
			//   j to [0, ny-2]  -> slice<'j'>(0, ny - 1)
			.order(space_blocking
			       ^ noarr::slice<'i'>(0, nx - 1)
			       ^ noarr::slice<'j'>(0, ny - 1))
			.for_each([=](auto state) {
				// state: i in [0, nx-2], j in [0, ny-2]
				auto state_i_jp1 = state + noarr::idx<'j'>(1);
				auto state_ip1_j = state + noarr::idx<'i'>(1);

				hz[state] = hz[state]
				            - c_07 * (
					            (ex[state_i_jp1] - ex[state]) +
					            (ey[state_ip1_j] - ey[state])
				            );
			});
	});
#pragma endscop
}

